// Explicit, bounded recovery for the same immutable migration and observed state.
using System;
using System.IO;
using System.Collections.Generic;
using C=HubSshMaintenanceCommon;
public sealed partial class HubSshMaintenanceState {
  Dictionary<string,object> recoveryGrant;
  string recoveryOperation;
  bool recoveryValidated;
  public void SetRecovery(Dictionary<string,object> grant,string operation){recoveryGrant=grant;recoveryOperation=operation;if(grant==null)return;C.Fields(grant,"version","migrationId","manifestSHA256","observedStateSHA256","issuedAt","expiresAt","operation");C.Num(grant,"version",1,1);C.Require(C.Str(grant,"migrationId",36)==(string)Manifest["migrationId"]&&C.Str(grant,"manifestSHA256",64)==ManifestHash&&C.Str(grant,"operation",32)==operation,"RECOVERY_BINDING_REJECTED");C.Require(operation=="resume"||operation=="rollback"||operation=="recover-pointer","RECOVERY_MODE_REJECTED");Digest(C.Str(grant,"observedStateSHA256",64));ValidateGrantTime();}
  void ValidateGrantTime(){C.Require(recoveryGrant!=null,"RECOVERY_GRANT_REQUIRED");int start=C.Num(recoveryGrant,"issuedAt",1,Int32.MaxValue),end=C.Num(recoveryGrant,"expiresAt",1,Int32.MaxValue),now=Now();C.Require(start<=now&&end>now&&end>start&&(long)end-start<=1800,"RECOVERY_GRANT_EXPIRED");}
  void PreAuthorize(){if(recoveryGrant!=null)ValidateGrantTime();else Fresh();}
  void ValidateRecoveryUnderLock(string operation,bool required){C.Require(sourceGate!=null&&destinationGate!=null&&transactionGate!=null,"RECOVERY_LOCK_REQUIRED");if(recoveryGrant==null){C.Require(!required,"RECOVERY_GRANT_REQUIRED");Fresh();return;}ValidateGrantTime();C.Require(recoveryOperation==operation&&C.Str(recoveryGrant,"observedStateSHA256",64)==ObservedStateHash(),"RECOVERY_OBSERVED_STATE_CHANGED");recoveryValidated=true;}
  string FileState(string path){if(path==PointerPath){byte[] bytes=pointer.ReadOptional("active-registration.json",65536);return bytes==null?"absent":C.Hash(bytes);}if(!C.Exists(path))return "absent";using(var f=C.HoldFile(path,65536))return C.Hash(C.Read(f));}
  public string ObservedStateHash(){C.Require(sourceGate!=null&&destinationGate!=null,"OBSERVATION_LOCK_REQUIRED");var files=new Dictionary<string,object>();foreach(string name in new string[]{"registration.bin","maintenance-intent.bin","forgotten.bin"})files["source/"+name]=FileState(Path.Combine(SourceRoot,name));foreach(string name in new string[]{"registration.bin","maintenance-intent.bin","activation.bin","forgotten.bin","pointer-prior.bin","rollback-intent.bin","rollback.bin"})files["destination/"+name]=FileState(At(name));for(int i=1;i<=Events.Length;i++)files["destination/migration-"+i.ToString("D4")+".bin"]=FileState(At("migration-"+i.ToString("D4")+".bin"));files["pointer"]=FileState(PointerPath);foreach(string leaf in new string[]{ActivationBackup(),RollbackBackup(),"active-registration-"+(string)Manifest["migrationId"]+".new","rollback-pointer-"+(string)Manifest["migrationId"]+".new"}){byte[] pointerBytes=pointer.ReadOptional(leaf,65536);files["pointer-root/"+leaf]=pointerBytes==null?"absent":C.Hash(pointerBytes);}
    bool sourceExists=HubSshVaultStore.Exists(SourceTarget),destinationExists=HubSshMaintenanceStore.Exists(DestinationTarget);byte[] a=null,b=null;string relation="absent";try{if(sourceExists)a=SourceSecret();if(destinationExists)b=DestinationSecret();relation=a!=null&&b!=null?(HubSshMaintenanceStore.Equal(a,b)?"equal":"different"):a!=null?"source-only":b!=null?"destination-only":"absent";}finally{if(a!=null)Array.Clear(a,0,a.Length);if(b!=null)Array.Clear(b,0,b.Length);}return C.Binding(new Dictionary<string,object>{{"version",1},{"manifestSHA256",ManifestHash},{"files",files},{"sourceExists",sourceExists},{"destinationExists",destinationExists},{"contentRelation",relation}});
  }
  Dictionary<string,object> ReadPrior(){var r=C.UnprotectFile(At("pointer-prior.bin"));C.Fields(r,"version","manifestSHA256","state","bytesBase64","sha256");C.Num(r,"version",1,1);C.Require(C.Str(r,"manifestSHA256",64)==ManifestHash,"POINTER_PRIOR_CHANGED");string state=C.Str(r,"state",16);C.Require(r["bytesBase64"] is string&&r["sha256"] is string,"POINTER_PRIOR_CHANGED");byte[] bytes=Convert.FromBase64String((string)r["bytesBase64"]);C.Require(bytes.Length<=4096&&Convert.ToBase64String(bytes)==(string)r["bytesBase64"],"POINTER_PRIOR_CHANGED");if((string)Manifest["pointerExpectedSHA256"]=="absent")C.Require(state=="absent"&&bytes.Length==0&&(string)r["sha256"]=="absent","POINTER_PRIOR_CHANGED");else C.Require(state=="present"&&bytes.Length>0&&C.Hash(bytes)==(string)Manifest["pointerExpectedSHA256"]&&(string)r["sha256"]==(string)Manifest["pointerExpectedSHA256"],"POINTER_PRIOR_CHANGED");return r;}
  void PreparePointerPrior(){RequireGate();if(C.Exists(At("pointer-prior.bin"))){ReadPrior();return;}C.Require(PointerState()=="old"&&!C.Exists(At("activation.bin")),"POINTER_PRIOR_MISSING");byte[] bytes=new byte[0];if((string)Manifest["pointerExpectedSHA256"]!="absent"){bytes=pointer.ReadOptional("active-registration.json",4096);C.Require(bytes!=null,"POINTER_PRIOR_MISSING");}var r=new Dictionary<string,object>{{"version",1},{"manifestSHA256",ManifestHash},{"state",bytes.Length==0?"absent":"present"},{"bytesBase64",Convert.ToBase64String(bytes)},{"sha256",bytes.Length==0?"absent":C.Hash(bytes)}};C.CreateFile(At("pointer-prior.bin"),C.Protected(C.Canon(r)));ReadPrior();}
  Dictionary<string,object> RollbackIntent(){return new Dictionary<string,object>{{"version",1},{"state","rollback-intent"},{"manifestSHA256",ManifestHash},{"binding",DestinationBinding},{"target",DestinationTarget}};}
  Dictionary<string,object> RollbackRecord(){return new Dictionary<string,object>{{"version",1},{"state","rolled-back"},{"manifestSHA256",ManifestHash},{"binding",DestinationBinding},{"target",DestinationTarget},{"sourceBinding",SourceBinding}};}
  void VerifyRollback(){SameProtected(At("rollback.bin"),RollbackRecord(),"ROLLBACK_RECORD_CHANGED");C.Require(PointerState()=="old"&&!HubSshMaintenanceStore.Exists(DestinationTarget)&&HubSshVaultStore.Exists(SourceTarget)&&!C.Exists(Path.Combine(SourceRoot,"forgotten.bin")),"ROLLBACK_STATE_CHANGED");byte[] source=SourceSecret();Array.Clear(source,0,source.Length);}
  void RestorePrior(){RequireGate();var prior=ReadPrior();string state=PointerState();if(state=="old"){byte[] backed=pointer.ReadOptional(RollbackBackup(),65536);C.Require(backed==null||C.Hash(backed)==C.Hash(C.Utf8.GetBytes(PointerText())),"ROLLBACK_BACKUP_CHANGED");return;}C.Require(state=="new"||state=="missing","ROLLBACK_POINTER_CHANGED");if((string)prior["state"]=="absent"){C.Require(state=="new","ROLLBACK_POINTER_CHANGED");pointer.Delete("active-registration.json",C.Hash(C.Utf8.GetBytes(PointerText())));}else{string temp="rollback-pointer-"+(string)Manifest["migrationId"]+".new";byte[] bytes=Convert.FromBase64String((string)prior["bytesBase64"]),existing=pointer.ReadOptional(temp,65536);if(existing==null)pointer.Create(temp,bytes);else C.Require(HubSshMaintenanceStore.Equal(existing,bytes),"ROLLBACK_POINTER_TEMP_CHANGED");string expectedNew=C.Hash(C.Utf8.GetBytes(PointerText()));byte[] rollbackBackup=pointer.ReadOptional(RollbackBackup(),65536);if(state=="missing"&&rollbackBackup==null){C.Require(Has("activation-intent")&&!Has("pointer-written"),"ROLLBACK_MISSING_POINTER_UNPROVEN");VerifyActivationBackup();pointer.Publish(temp,"active-registration.json",C.Hash(bytes),"absent",RollbackBackup(),null);}else pointer.Publish(temp,"active-registration.json",C.Hash(bytes),expectedNew,RollbackBackup(),delegate{Checkpoint("AFTER_ROLLBACK_DISPLACE");});}C.Require(PointerState()=="old","ROLLBACK_POINTER_UNVERIFIED");}

  public Dictionary<string,object> Rollback(){PreAuthorize();AcquireTransaction();AcquireBoth();ValidateRecoveryUnderLock("rollback",false);C.Require(AnyIntent(),"ROLLBACK_INTENT_MISSING");VerifyIntents(false);LoadJournal();C.Require(HubSshVaultStore.Exists(SourceTarget)&&!C.Exists(Path.Combine(SourceRoot,"forgotten.bin"))&&!Has("source-deleted")&&!Has("completed"),"ROLLBACK_SOURCE_RETIRED");if(C.Exists(At("rollback.bin"))){VerifyRollback();return C.Result("rolled-back");}ReadPrior();C.Require(PointerState()=="old"||PointerState()=="new"||PointerState()=="missing","ROLLBACK_POINTER_CHANGED");bool destinationExists=HubSshMaintenanceStore.Exists(DestinationTarget);if(destinationExists)EqualSecrets();else C.Require(C.Exists(At("rollback-intent.bin"))||!Has("destination-stored"),"ROLLBACK_DESTINATION_MISSING");if(!C.Exists(At("rollback-intent.bin")))C.CreateFile(At("rollback-intent.bin"),C.Protected(C.Canon(RollbackIntent())));SameProtected(At("rollback-intent.bin"),RollbackIntent(),"ROLLBACK_INTENT_CHANGED");Checkpoint("AFTER_ROLLBACK_INTENT");RestorePrior();Checkpoint("AFTER_ROLLBACK_POINTER");if(HubSshMaintenanceStore.Exists(DestinationTarget)){byte[] source=null;try{source=SourceSecret();HubSshMaintenanceStore.Delete(DestinationTarget,(string)Destination["user"],source,Comment);}finally{if(source!=null)Array.Clear(source,0,source.Length);}}C.Require(!HubSshMaintenanceStore.Exists(DestinationTarget),"ROLLBACK_DESTINATION_DELETE_UNVERIFIED");Checkpoint("AFTER_ROLLBACK_DELETE");C.CreateFile(At("rollback.bin"),C.Protected(C.Canon(RollbackRecord())));VerifyRollback();Checkpoint("AFTER_ROLLBACK_RECORD");ReleaseBoth();Fresh();SourceProbe();AcquireBoth();VerifyRollback();C.Event("ROLLED_BACK");return C.Result("rolled-back");}
  public Dictionary<string,object> RecoverPointer(){PreAuthorize();AcquireTransaction();AcquireBoth();C.Require(recoveryGrant!=null,"RECOVERY_GRANT_REQUIRED");VerifyIntents();LoadJournal();C.Require(Has("source-delete-intent")&&Has("destination-active")&&!HubSshVaultStore.Exists(SourceTarget)&&HasPending()&&!C.Exists(At("rollback.bin"))&&!C.Exists(At("rollback-intent.bin")),"POINTER_RECOVERY_STATE_REJECTED");SameProtected(At("activation.bin"),Activation(),"ACTIVATION_CHANGED");CheckSourceTomb();byte[] secret=DestinationSecret();Array.Clear(secret,0,secret.Length);var intent=new Dictionary<string,object>{{"version",1},{"manifestSHA256",ManifestHash},{"operation","recover-pointer"},{"grant",recoveryGrant}};string name="recover-"+C.Binding(recoveryGrant).Substring(0,32)+".bin";
    // An interrupted pointer write may already have succeeded. Replaying the
    // exact stored grant then performs no mutation and verifies the result.
    if(C.Exists(At(name))&&PointerState()=="new"){SameProtected(At(name),intent,"POINTER_RECOVERY_INTENT_CHANGED");C.Require(Active(),"POINTER_RECOVERY_UNVERIFIED");return C.Result("pointer-restored");}
    ValidateRecoveryUnderLock("recover-pointer",true);C.Require(pointer.ReadOptional("active-registration.json",65536)==null,"POINTER_RECOVERY_REQUIRES_ABSENCE");if(!C.Exists(At(name)))C.CreateFile(At(name),C.Protected(C.Canon(intent)));SameProtected(At(name),intent,"POINTER_RECOVERY_INTENT_CHANGED");Checkpoint("AFTER_POINTER_RECOVERY_INTENT");pointer.Create("active-registration.json",C.Utf8.GetBytes(PointerText()));C.Require(Active(),"POINTER_RECOVERY_UNVERIFIED");Checkpoint("AFTER_POINTER_RECOVERY_WRITE");C.Event("POINTER_RESTORED");return C.Result("pointer-restored");}
}
